if(location.search)history.replaceState(null,'',location.pathname);
let token=localStorage.getItem('nexus_token'),page='dashboard',currentUser=null,invoiceStatusFilter='all';const $=s=>document.querySelector(s);const api=async(path,opt={})=>{opt.headers={...(opt.headers||{}),Authorization:`Bearer ${token}`,'Content-Type':'application/json'};let r=await fetch(path,opt);if(r.status===401){logout();throw Error('Unauthorized')}let j=await r.json();if(!r.ok)throw Error(j.detail||'Request failed');return j};
function logout(){localStorage.removeItem('nexus_token');token=null;$('#app').classList.add('hidden');$('#login').classList.remove('hidden')}
$('#loginForm').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(fd)}),j=await r.json();if(!r.ok){$('#loginErr').textContent=j.detail||'Login failed';return}token=j.access_token;localStorage.setItem('nexus_token',token);showApp()};$('#logout').onclick=logout;$('#mobileMenu').onclick=()=>document.querySelector('aside').classList.toggle('open');
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{page=b.dataset.page;document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('aside').classList.remove('open');render()});$('#lang').onclick=()=>{document.documentElement.dir=document.documentElement.dir==='rtl'?'ltr':'rtl';document.documentElement.lang=document.documentElement.dir==='rtl'?'ar':'en'};
const money=n=>new Intl.NumberFormat('en-EG',{maximumFractionDigits:2}).format(n||0),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
async function showApp(){if(!token)return;currentUser=await api('/api/auth/me');$('#userName').textContent=currentUser.username+' · '+currentUser.role;$('#usersNav').classList.toggle('hidden',currentUser.role!=='admin');if(currentUser.role!=='admin'&&page==='users')page='dashboard';$('#login').classList.add('hidden');$('#app').classList.remove('hidden');render()}
async function render(){let titles={dashboard:'Dashboard',accounting:'Accounting',inventory:'Inventory',purchasing:'Purchasing',sales:'Sales',manufacturing:'Manufacturing',partners:'Customers & Suppliers',users:'User Administration'};$('#pageTitle').textContent=titles[page];let c=$('#content');try{if(page==='dashboard')return dashboard(c);if(page==='inventory')return inventory(c);if(page==='accounting')return accounting(c);if(page==='purchasing'||page==='sales')return invoices(c,page);if(page==='manufacturing')return manufacturing(c);if(page==='users')return users(c);return partners(c)}catch(e){c.innerHTML=`<div class="page"><div class="card error">${esc(e.message)}</div></div>`}}
async function dashboard(c){let d=await api('/api/dashboard');c.innerHTML=`<div class="page"><div class="hero"><div><h1>ERP Control Center</h1><div class="muted">Real-time operational and financial snapshot.</div></div><button class="primary" onclick="page='purchasing';render()">+ New Purchase</button></div><div class="grid"><div class="card kpi"><div class="label">Inventory Value</div><div class="value">${money(d.inventory_value)}</div><div class="trend">EGP</div></div><div class="card kpi"><div class="label">Sales</div><div class="value">${money(d.sales)}</div><div class="trend">Posted invoices</div></div><div class="card kpi"><div class="label">Purchases</div><div class="value">${money(d.purchases)}</div><div class="trend">Posted invoices</div></div><div class="card kpi"><div class="label">Products</div><div class="value">${d.products}</div><div class="trend">${d.customers} customers • ${d.suppliers} suppliers</div></div><div class="card kpi"><div class="label">Awaiting Review</div><div class="value">${d.workflow_pending}</div><div class="trend">Submitted or approved invoices</div></div></div><div class="two"><div class="card"><h3>Low Stock Alerts</h3>${d.low_stock.length?`<table class="table"><tr><th>SKU</th><th>Item</th><th>On hand</th><th>Reorder</th></tr>${d.low_stock.map(x=>`<tr><td>${esc(x.sku)}</td><td>${esc(x.name)}</td><td><span class="badge out">${x.qty}</span></td><td>${x.reorder_level}</td></tr>`).join('')}</table>`:'<div class="empty">No low-stock items.</div>'}</div><div class="card"><h3>Integrated Flow</h3><div class="flow"><b>Purchase</b><span>→</span><b>Inventory</b><span>→</span><b>Payables</b></div><div class="flow"><b>Production</b><span>→</span><b>Finished Goods</b><span>→</span><b>Cost</b></div><div class="flow"><b>Sales</b><span>→</span><b>Stock OUT</b><span>→</span><b>Receivables</b></div></div></div></div>`}
async function inventory(c){let [ps,m,wh]=await Promise.all([api('/api/products'),api('/api/stock-moves'),api('/api/warehouses')]);c.innerHTML=`<div class="page"><div class="hero"><div><h1>Inventory</h1><div class="muted">Products, warehouses, stock and movement ledger.</div></div><button class="primary" onclick="addProduct()">+ Product</button></div><div class="card"><div class="toolbar"><button onclick="addWarehouse()">+ Warehouse</button><span class="muted">${wh.length} warehouse(s)</span></div><table class="table"><tr><th>SKU</th><th>Product</th><th>Category</th><th>Unit</th><th>On Hand</th><th>Cost</th><th>Sale Price</th></tr>${ps.map(p=>`<tr><td><b>${esc(p.sku)}</b></td><td>${esc(p.name)}</td><td>${esc(p.category)}</td><td>${p.unit}</td><td>${p.qty}</td><td>${money(p.cost)}</td><td>${money(p.sale_price)}</td></tr>`).join('')}</table></div><div class="card" style="margin-top:16px"><h3>Recent Stock Movements</h3><table class="table"><tr><th>Date</th><th>Item</th><th>Warehouse</th><th>Direction</th><th>Qty</th><th>Reference</th></tr>${m.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${esc(x.product)}</td><td>${esc(x.warehouse)}</td><td><span class="badge ${x.direction==='IN'?'in':'out'}">${x.direction}</span></td><td>${x.qty}</td><td>${x.ref_type} / ${x.ref_no}</td></tr>`).join('')}</table></div></div>`}
async function accounting(c){let [a,j,t]=await Promise.all([api('/api/accounts'),api('/api/journals'),api('/api/trial-balance')]);c.innerHTML=`<div class="page"><div class="hero"><div><h1>Accounting</h1><div class="muted">Double-entry ledger • VAT 14% • trial balance.</div></div></div><div class="two"><div class="card"><h3>Chart of Accounts</h3><table class="table"><tr><th>Code</th><th>Account</th><th>Type</th></tr>${a.map(x=>`<tr><td>${x.code}</td><td>${esc(x.name)}</td><td>${x.type}</td></tr>`).join('')}</table></div><div class="card"><h3>Trial Balance</h3><table class="table"><tr><th>Account</th><th>Debit</th><th>Credit</th></tr>${t.map(x=>`<tr><td>${x.code} - ${esc(x.name)}</td><td>${money(x.debit)}</td><td>${money(x.credit)}</td></tr>`).join('')||'<tr><td colspan="3">No posted entries.</td></tr>'}</table></div></div><div class="card" style="margin-top:16px"><h3>Journal Entries</h3>${j.map(x=>`<div class="journal"><b>${x.entry_no}</b> — ${esc(x.description)}<table class="table"><tr><th>Account</th><th>Debit</th><th>Credit</th></tr>${x.lines.map(l=>`<tr><td>${esc(l.account)}</td><td>${money(l.debit)}</td><td>${money(l.credit)}</td></tr>`).join('')}</table></div>`).join('')||'<div class="empty">No journal entries.</div>'}</div></div>`}
async function invoiceAction(id,action){let verb=action==='post'?'post this approved invoice':action+' this invoice';if(!confirm('Do you want to '+verb+'?'))return;try{let path=action==='post'?'/api/invoices/'+id+'/post':'/api/invoices/'+id+'/workflow',opt=action==='post'?{method:'POST'}:{method:'POST',body:JSON.stringify({action})};await api(path,opt);render()}catch(err){alert(err.message)}}
function invoiceActionButtons(x){if(!currentUser||!['admin','accountant'].includes(currentUser.role))return 'View only';if(x.status==='posted'||x.status==='cancelled')return '—';let buttons=[];if(x.status==='draft')buttons.push('<button onclick="invoiceAction('+x.id+',\'submit\')">Submit</button>');if(x.status==='submitted')buttons.push('<button onclick="invoiceAction('+x.id+',\'approve\')">Approve</button>','<button onclick="invoiceAction('+x.id+',\'return\')">Return</button>');if(x.status==='approved')buttons.push('<button class="primary" onclick="invoiceAction('+x.id+',\'post\')">Post</button>','<button onclick="invoiceAction('+x.id+',\'return\')">Return</button>');buttons.push('<button class="danger" onclick="invoiceAction('+x.id+',\'cancel\')">Cancel</button>');return buttons.join(' ')}
async function invoices(c,type){let kind=type==='purchasing'?'purchase':'sale',[ps,parties,whs,inv]=await Promise.all([api('/api/products'),api('/api/parties'),api('/api/warehouses'),api('/api/invoices')]);let pp=parties.filter(p=>p.kind===(kind==='purchase'?'supplier':'customer')), allRows=inv.filter(x=>x.kind===kind),rows=invoiceStatusFilter==='all'?allRows:allRows.filter(x=>x.status===invoiceStatusFilter);c.innerHTML=`<div class="page"><div class="hero"><div><h1>${kind==='purchase'?'Purchasing':'Sales'}</h1><div class="muted">Create a draft for review, then approve and post it. Immediate posting remains available when appropriate.</div></div><button class="primary" onclick='newInvoice(${JSON.stringify(kind)},${JSON.stringify(ps)},${JSON.stringify(pp)},${JSON.stringify(whs)})'>+ New ${kind==='purchase'?'Purchase':'Sales'} Invoice</button></div><div class="card"><div class="toolbar"><h3>Invoices</h3><select aria-label="Invoice status filter" onchange="invoiceStatusFilter=this.value;render()"><option value="all" ${invoiceStatusFilter==='all'?'selected':''}>All statuses</option><option value="draft" ${invoiceStatusFilter==='draft'?'selected':''}>Draft</option><option value="submitted" ${invoiceStatusFilter==='submitted'?'selected':''}>Submitted</option><option value="approved" ${invoiceStatusFilter==='approved'?'selected':''}>Approved</option><option value="posted" ${invoiceStatusFilter==='posted'?'selected':''}>Posted</option><option value="cancelled" ${invoiceStatusFilter==='cancelled'?'selected':''}>Cancelled</option></select></div><table class="table"><tr><th>Invoice</th><th>Party</th><th>Subtotal</th><th>VAT</th><th>Total</th><th>Status</th><th>Date</th><th>Actions</th></tr>${rows.map(x=>`<tr><td><b>${x.invoice_no}</b></td><td>${esc(x.party)}</td><td>${money(x.subtotal)}</td><td>${money(x.tax)}</td><td>${money(x.total)}</td><td><span class="badge ${x.status==='posted'?'in':x.status==='cancelled'?'out':''}">${esc(x.status)}</span></td><td>${new Date(x.created_at).toLocaleString()}</td><td>${invoiceActionButtons(x)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No invoices.</td></tr>'}</table></div></div>`}
async function manufacturing(c){let [boms,ps,whs,prods]=await Promise.all([api('/api/boms'),api('/api/products'),api('/api/warehouses'),api('/api/productions')]);c.innerHTML=`<div class="page"><div class="hero"><div><h1>Manufacturing</h1><div class="muted">BOMs, material requirements, production and batch costing.</div></div><div class="toolbar"><button onclick='newBOM(${JSON.stringify(ps)})'>+ BOM</button><button class="primary" onclick='newProduction(${JSON.stringify(boms)},${JSON.stringify(whs)})'>+ Production Order</button></div></div><div class="two"><div class="card"><h3>Bill of Materials</h3>${boms.map(b=>`<div class="bom"><b>${esc(b.sku)} — ${esc(b.product)}</b><div class="muted">Output: ${b.quantity} ${esc(ps.find(p=>p.id===b.product_id)?.unit||'')}</div><ul>${b.lines.map(l=>`<li>${l.qty} × ${esc(l.sku)} — ${esc(l.name)}</li>`).join('')}</ul></div>`).join('')||'<div class="empty">No BOMs.</div>'}</div><div class="card"><h3>Production Orders</h3><table class="table"><tr><th>No.</th><th>Product</th><th>Qty</th><th>Cost</th><th>Status</th></tr>${prods.map(p=>`<tr><td>${p.production_no}</td><td>${esc(p.sku)} — ${esc(p.product)}</td><td>${p.qty}</td><td>${money(p.total_cost)}</td><td><span class="badge in">${p.status}</span></td></tr>`).join('')||'<tr><td colspan="5">No production orders.</td></tr>'}</table></div></div></div>`}
async function partners(c){let p=await api('/api/parties');c.innerHTML=`<div class="page"><div class="hero"><div><h1>Customers & Suppliers</h1><div class="muted">One shared master-data registry for all transactions.</div></div><button class="primary" onclick="addParty()">+ Add Party</button></div><div class="card"><table class="table"><tr><th>Code</th><th>Name</th><th>Type</th><th>Phone</th><th>Tax ID</th></tr>${p.map(x=>`<tr><td>${x.code}</td><td><b>${esc(x.name)}</b></td><td>${x.kind}</td><td>${esc(x.phone)}</td><td>${esc(x.tax_id)}</td></tr>`).join('')}</table></div></div>`}

async function users(c){if(!currentUser||currentUser.role!=='admin'){page='dashboard';return render()}let us=await api('/api/users');c.innerHTML='<div class="page"><div class="hero"><div><h1>User Administration</h1><div class="muted">Manage accounts, responsibilities and access status.</div></div><button class="primary" onclick="newUser()">+ New User</button></div><div class="card"><table class="table"><tr><th>Username</th><th>Role</th><th>Status</th><th></th></tr>'+us.map(u=>'<tr><td><b>'+esc(u.username)+'</b></td><td>'+esc(u.role)+'</td><td><span class="badge '+(u.active?'in':'out')+'">'+(u.active?'Active':'Inactive')+'</span></td><td><button class="manage-user" data-id="'+u.id+'">Manage</button></td></tr>').join('')+'</table></div></div>';c.querySelectorAll('.manage-user').forEach(b=>b.onclick=()=>manageUser(us.find(u=>u.id===+b.dataset.id)))}
function newUser(){let m=modal('<div class="card"><div class="modal-head"><div><h2>New User</h2><p class="muted">Give only the role needed for the person’s work.</p></div><button class="x">×</button></div><form id="newUser"><div class="form-grid"><input name="username" placeholder="Username" minlength="3" required><input name="password" type="password" placeholder="Temporary password" minlength="8" required><select name="role"><option value="inventory">Inventory</option><option value="accountant">Accountant</option><option value="admin">Administrator</option></select></div><button class="primary">Create User</button><div id="err"></div></form></div>');m.querySelector('#newUser').onsubmit=async e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));try{await api('/api/users',{method:'POST',body:JSON.stringify(o)});m.remove();render()}catch(err){m.querySelector('#err').textContent=err.message}}}
function manageUser(u){let m=modal('<div class="card"><div class="modal-head"><div><h2>Manage '+esc(u.username)+'</h2><p class="muted">Change role, account status, or reset the password.</p></div><button class="x">×</button></div><form id="manageUser"><div class="form-grid"><select name="role"><option value="inventory" '+(u.role==='inventory'?'selected':'')+'>Inventory</option><option value="accountant" '+(u.role==='accountant'?'selected':'')+'>Accountant</option><option value="admin" '+(u.role==='admin'?'selected':'')+'>Administrator</option></select><label class="check"><input name="active" type="checkbox" '+(u.active?'checked':'')+'> Active account</label><input name="password" type="password" placeholder="New password - optional" minlength="8"></div><button class="primary">Save Changes</button><div id="err"></div></form></div>');m.querySelector('#manageUser').onsubmit=async e=>{e.preventDefault();let o={role:e.target.role.value,active:e.target.active.checked},password=e.target.password.value;if(password)o.password=password;try{await api('/api/users/'+u.id,{method:'PATCH',body:JSON.stringify(o)});m.remove();render()}catch(err){m.querySelector('#err').textContent=err.message}}}
function modal(html){let d=document.createElement('div');d.className='modal';d.innerHTML=html;document.body.appendChild(d);d.querySelector('.x')?.addEventListener('click',()=>d.remove());return d}
async function newInvoice(kind,ps,parties,whs){if(!currentUser||!['admin','accountant'].includes(currentUser.role)){alert('Your role has view-only access to invoices.');return}let m=modal(`<div class="card"><div class="modal-head"><div><h2>New ${kind==='purchase'?'Purchase':'Sales'} Invoice</h2><p class="muted">VAT default 14% • posting is atomic.</p></div><button class="x">×</button></div><form id="invForm"><div class="form-grid"><select name="party_id">${parties.map(x=>`<option value="${x.id}">${esc(x.code)} — ${esc(x.name)}</option>`).join('')}</select><select name="warehouse_id">${whs.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><input name="tax_rate" type="number" value="14" step="0.01" min="0" placeholder="VAT %"></div><div id="lines"></div><button type="button" class="toolbar" id="addLine">+ Add line</button><button type="button" id="saveDraft">Save as Draft</button><button class="primary">Post Invoice</button><div id="err"></div></form></div>`);let lines=m.querySelector('#lines');const add=()=>{let r=document.createElement('div');r.className='line';r.innerHTML=`<select class="prod">${ps.map(x=>`<option value="${x.id}" data-price="${kind==='purchase'?x.cost:x.sale_price}">${esc(x.sku)} — ${esc(x.name)}</option>`).join('')}</select><input class="qty" type="number" min="0.001" step="0.001" value="1"><input class="price" type="number" min="0" step="0.01"><button type="button" class="x remove">×</button>`;r.querySelector('.prod').onchange=e=>r.querySelector('.price').value=e.target.selectedOptions[0].dataset.price;r.querySelector('.prod').dispatchEvent(new Event('change'));r.querySelector('.remove').onclick=()=>r.remove();lines.appendChild(r)};m.querySelector('#addLine').onclick=add;add();const saveInvoice=async postNow=>{let rows=[...lines.children];if(!rows.length)return;m.querySelector('#err').textContent=postNow?'Posting...':'Saving draft...';let payload={kind,party_id:+m.querySelector('#invForm').party_id.value,warehouse_id:+m.querySelector('#invForm').warehouse_id.value,tax_rate:+m.querySelector('#invForm').tax_rate.value,post_now:postNow,lines:rows.map(r=>({product_id:+r.querySelector('.prod').value,qty:+r.querySelector('.qty').value,unit_price:+r.querySelector('.price').value}))};try{let r=await api('/api/invoices',{method:'POST',body:JSON.stringify(payload)});m.remove();alert((postNow?'Posted ':'Draft saved ')+r.invoice_no);render()}catch(err){m.querySelector('#err').textContent=err.message}};m.querySelector('#saveDraft').onclick=()=>saveInvoice(false);m.querySelector('#invForm').onsubmit=e=>{e.preventDefault();saveInvoice(true)}}
async function addProduct(){let m=modal(`<div class="card"><div class="modal-head"><h2>New Product</h2><button class="x">×</button></div><form id="p"><div class="form-grid"><input name="sku" placeholder="SKU" required><input name="name" placeholder="Product name" required><input name="category" value="Raw Material"><input name="unit" value="KG"><input name="cost" type="number" value="0"><input name="sale_price" type="number" value="0"><input name="reorder_level" type="number" value="0"></div><button class="primary">Save Product</button><div id="err"></div></form></div>`);m.querySelector('#p').onsubmit=async e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));o.cost=+o.cost;o.sale_price=+o.sale_price;o.reorder_level=+o.reorder_level;try{await api('/api/products',{method:'POST',body:JSON.stringify(o)});m.remove();render()}catch(err){m.querySelector('#err').textContent=err.message}}}
async function addWarehouse(){let m=modal(`<div class="card"><div class="modal-head"><h2>New Warehouse</h2><button class="x">×</button></div><form id="w"><input name="code" placeholder="WH-02" required><input name="name" placeholder="Warehouse name" required><button class="primary">Save</button></form></div>`);m.querySelector('#w').onsubmit=async e=>{e.preventDefault();try{await api('/api/warehouses',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});m.remove();render()}catch(err){alert(err.message)}}}
async function addParty(){let m=modal(`<div class="card"><div class="modal-head"><h2>Add Customer / Supplier</h2><button class="x">×</button></div><form id="p"><div class="form-grid"><input name="code" placeholder="CUS-002" required><input name="name" placeholder="Company name" required><select name="kind"><option value="customer">Customer</option><option value="supplier">Supplier</option></select><input name="phone" placeholder="Phone"><input name="tax_id" placeholder="Tax ID"></div><button class="primary">Save</button><div id="err"></div></form></div>`);m.querySelector('#p').onsubmit=async e=>{e.preventDefault();try{await api('/api/parties',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});m.remove();render()}catch(err){m.querySelector('#err').textContent=err.message}}}
async function newBOM(ps){let fg=ps.filter(p=>p.category.toLowerCase().includes('finished'));let m=modal(`<div class="card"><div class="modal-head"><h2>New Bill of Materials</h2><button class="x">×</button></div><form id="b"><select name="product_id">${fg.map(p=>`<option value="${p.id}">${esc(p.sku)} — ${esc(p.name)}</option>`).join('')}</select><input name="quantity" type="number" value="1" min="0.001" step="0.001"><div id="bl"></div><button type="button" id="addB" class="toolbar">+ Component</button><button class="primary">Save BOM</button><div id="err"></div></form></div>`);let box=m.querySelector('#bl');const add=()=>{let r=document.createElement('div');r.className='line';r.innerHTML=`<select class="cp">${ps.filter(p=>!fg.includes(p)).map(p=>`<option value="${p.id}">${esc(p.sku)} — ${esc(p.name)}</option>`).join('')}</select><input class="cq" type="number" value="1" min="0.001" step="0.001"><button type="button" class="x remove">×</button>`;r.querySelector('.remove').onclick=()=>r.remove();box.appendChild(r)};m.querySelector('#addB').onclick=add;add();m.querySelector('#b').onsubmit=async e=>{e.preventDefault();let rows=[...box.children];try{await api('/api/boms',{method:'POST',body:JSON.stringify({product_id:+e.target.product_id.value,quantity:+e.target.quantity.value,lines:rows.map(r=>({component_id:+r.querySelector('.cp').value,qty:+r.querySelector('.cq').value}))})});m.remove();render()}catch(err){m.querySelector('#err').textContent=err.message}}}
async function newProduction(boms,whs){let m=modal(`<div class="card"><div class="modal-head"><h2>New Production Order</h2><button class="x">×</button></div><form id="p"><select name="bom_id">${boms.map(b=>`<option value="${b.id}">${esc(b.sku)} — ${esc(b.product)}</option>`).join('')}</select><select name="warehouse_id">${whs.map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}</select><input name="qty" type="number" value="1" min="0.001" step="0.001"><button class="primary">Post Production</button><div id="err"></div></form></div>`);m.querySelector('#p').onsubmit=async e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));o.bom_id=+o.bom_id;o.warehouse_id=+o.warehouse_id;o.qty=+o.qty;try{let r=await api('/api/productions',{method:'POST',body:JSON.stringify(o)});m.remove();alert(`Production ${r.production_no}\nTotal cost EGP ${money(r.total_cost)}\nUnit cost EGP ${money(r.unit_cost)}`);render()}catch(err){m.querySelector('#err').textContent=err.message}}}
if(token)showApp();


const renderAccountingBase=accounting;
accounting=async function(c){
  await renderAccountingBase(c);
  if(!currentUser||!['admin','accountant'].includes(currentUser.role))return;
  const payments=await api('/api/payments');
  const hero=c.querySelector('.hero');
  const button=document.createElement('button');
  button.className='primary';button.textContent='+ Record Payment';button.onclick=newPayment;hero.appendChild(button);
  const card=document.createElement('div');card.className='card';card.style.marginTop='16px';
  card.innerHTML='<h3>Receipts & Payments</h3><table class="table"><tr><th>Reference</th><th>Type</th><th>Party</th><th>Account</th><th>Amount</th><th>Date</th><th>Action</th></tr>'+payments.map(p=>'<tr><td><b>'+esc(p.payment_no)+'</b></td><td>'+esc(p.kind)+'</td><td>'+esc(p.party)+'</td><td>'+esc(p.account)+'</td><td>'+money(p.amount)+'</td><td>'+new Date(p.created_at).toLocaleString()+'</td><td><button class="danger payment-void" data-id="'+p.id+'">Void</button></td></tr>').join('')+'</table>'+(payments.length?'':'<div class="empty">No recorded receipts or payments.</div>');c.querySelector('.page').appendChild(card);card.querySelectorAll('.payment-void').forEach(b=>b.onclick=()=>window.voidPaymentById(b.dataset.id));
}
async function newPayment(){
  let [parties,accounts]=await Promise.all([api('/api/parties'),api('/api/accounts')]);
  const cashAccounts=accounts.filter(a=>a.code==='1000'||a.code==='1100');
  let m=modal('<div class="card"><div class="modal-head"><div><h2>Record Receipt or Payment</h2><p class="muted">Creates a balanced cash or bank journal entry.</p></div><button class="x">×</button></div><form id="paymentForm"><div class="form-grid"><select name="kind"><option value="receipt">Customer receipt</option><option value="payment">Supplier payment</option></select><select name="party_id"></select><select name="account_code">'+cashAccounts.map(a=>'<option value="'+a.code+'">'+esc(a.code)+' - '+esc(a.name)+'</option>').join('')+'</select><input name="amount" type="number" min="0.01" step="0.01" placeholder="Amount" required></div><button class="primary">Record</button><div id="err"></div></form></div>');
  const form=m.querySelector('#paymentForm'), partySelect=form.party_id;
  const refreshParties=()=>{let required=form.kind.value==='receipt'?'customer':'supplier';partySelect.innerHTML=parties.filter(p=>p.kind===required).map(p=>'<option value="'+p.id+'">'+esc(p.code)+' - '+esc(p.name)+'</option>').join('')};
  form.kind.onchange=refreshParties;refreshParties();
  form.onsubmit=async e=>{e.preventDefault();let payload={kind:form.kind.value,party_id:+form.party_id.value,account_code:form.account_code.value,amount:+form.amount.value};try{let r=await api('/api/payments',{method:'POST',body:JSON.stringify(payload)});m.remove();alert('Recorded '+r.payment_no);render()}catch(err){form.querySelector('#err').textContent=err.message}};
}


const paymentFormBase=newPayment;
newPayment=async function(){
 let [parties,accounts]=await Promise.all([api('/api/parties'),api('/api/accounts')]);let cash=accounts.filter(a=>a.code==='1000'||a.code==='1100');
 let m=modal('<div class="card"><div class="modal-head"><div><h2>Record & Allocate Payment</h2><p class="muted">Apply the payment to one posted invoice.</p></div><button class="x">×</button></div><form id="allocationForm"><div class="form-grid"><select name="kind"><option value="receipt">Customer receipt</option><option value="payment">Supplier payment</option></select><select name="party_id"></select><select name="invoice_id"></select><select name="account_code">'+cash.map(a=>'<option value="'+a.code+'">'+esc(a.code)+' - '+esc(a.name)+'</option>').join('')+'</select><input name="amount" type="number" min="0.01" step="0.01" required></div><button class="primary">Record Allocation</button><div id="err"></div></form></div>');let f=m.querySelector('#allocationForm');
 let refresh=async()=>{let type=f.kind.value==='receipt'?'customer':'supplier';f.party_id.innerHTML=parties.filter(p=>p.kind===type).map(p=>'<option value="'+p.id+'">'+esc(p.code)+' - '+esc(p.name)+'</option>').join('');let inv=await api('/api/open-invoices?kind='+f.kind.value+'&party_id='+f.party_id.value);f.invoice_id.innerHTML=inv.map(x=>'<option value="'+x.id+'" data-balance="'+x.balance+'">'+esc(x.invoice_no)+' - balance '+money(x.balance)+'</option>').join('');if(inv.length)f.amount.value=inv[0].balance};
 f.kind.onchange=refresh;f.party_id.onchange=refresh;await refresh();f.onsubmit=async e=>{e.preventDefault();let p={kind:f.kind.value,party_id:+f.party_id.value,invoice_id:+f.invoice_id.value,account_code:f.account_code.value,amount:+f.amount.value};try{await api('/api/payments',{method:'POST',body:JSON.stringify(p)});m.remove();render()}catch(err){f.querySelector('#err').textContent=err.message}}}



