window.newCommercialDocument=async function(kind){const [parties,products]=await Promise.all([api('/api/parties'),api('/api/products')]);const purchase=kind==='purchase',endpoint=purchase?'/api/purchase-orders':'/api/sales-quotations',partyKind=purchase?'supplier':'customer',title=purchase?'Purchase Order':'Sales Quotation',partiesForKind=parties.filter(p=>p.kind===partyKind);const m=modal('<div class="card"><div class="modal-head"><div><h2>New '+title+'</h2><p class="muted">Add products and quantities. The document total is calculated from its lines.</p></div><button class="x">×</button></div><form id="commercialForm"><select name="party_id">'+partiesForKind.map(p=>'<option value="'+p.id+'">'+esc(p.code)+' - '+esc(p.name)+'</option>').join('')+'</select><div id="commercialLines"></div><div class="toolbar"><button type="button" id="addCommercialLine">+ Add line</button><b id="commercialTotal">EGP 0</b></div><button class="primary">Create Draft '+title+'</button><div id="err"></div></form></div>');const form=m.querySelector('#commercialForm'),box=m.querySelector('#commercialLines'),total=m.querySelector('#commercialTotal');const recalc=()=>{const amount=[...box.children].reduce((sum,row)=>sum+(+row.querySelector('.qty').value||0)*(+row.querySelector('.price').value||0),0);total.textContent='EGP '+money(amount)};const add=()=>{const row=document.createElement('div');row.className='line';row.innerHTML='<select class="prod">'+products.map(p=>'<option value="'+p.id+'" data-price="'+(purchase?p.cost:p.sale_price)+'">'+esc(p.sku)+' - '+esc(p.name)+'</option>').join('')+'</select><input class="qty" type="number" min="0.001" step="0.001" value="1"><input class="price" type="number" min="0" step="0.01"><button type="button" class="x remove">×</button>';const product=row.querySelector('.prod'),price=row.querySelector('.price');product.onchange=()=>{price.value=product.selectedOptions[0].dataset.price;recalc()};price.oninput=recalc;row.querySelector('.qty').oninput=recalc;row.querySelector('.remove').onclick=()=>{row.remove();recalc()};box.appendChild(row);product.dispatchEvent(new Event('change'))};m.querySelector('#addCommercialLine').onclick=add;add();form.onsubmit=async e=>{e.preventDefault();const lines=[...box.children].map(row=>({product_id:+row.querySelector('.prod').value,qty:+row.querySelector('.qty').value,unit_price:+row.querySelector('.price').value}));if(!lines.length){form.querySelector('#err').textContent='Add at least one line';return}try{const payload=purchase?{supplier_id:+form.party_id.value,lines}:{customer_id:+form.party_id.value,lines};await api(endpoint,{method:'POST',body:JSON.stringify(payload)});m.remove();render()}catch(err){form.querySelector('#err').textContent=err.message}}};
