window.viewCommercialDocument=async function(kind,id){try{const record=await api((kind==='purchase'?'/api/purchase-orders/':'/api/sales-quotations/')+id);const lines=record.lines||[];const m=modal('<div class="card"><div class="modal-head"><div><h2>'+esc(record.po_no||record.quote_no)+'</h2><p class="muted">'+esc(record.supplier||record.customer)+' - '+esc(record.status)+'</p></div><button class="x">×</button></div><table class="table"><tr><th>SKU</th><th>Product</th><th>Qty</th><th>Unit price</th><th>Line total</th></tr>'+lines.map(line=>'<tr><td>'+esc(line.sku)+'</td><td>'+esc(line.product)+'</td><td>'+line.qty+'</td><td>'+money(line.unit_price)+'</td><td>'+money(line.line_total)+'</td></tr>').join('')+(lines.length?'':'<tr><td colspan="5" class="empty">Legacy total-only document - no stored product lines.</td></tr>')+'</table><h3 style="text-align:right">Total: EGP '+money(record.total)+'</h3></div>');return m}catch(err){alert(err.message)}};
