inventory=async function(c){await renderStockAdjustmentButton(c);if(!currentUser||!['admin','inventory'].includes(currentUser.role))return;const hero=c.querySelector('.hero');const button=document.createElement('button');button.className='primary';button.textContent='Adjust Stock';button.onclick=window.newStockAdjustment;hero.appendChild(button)};


const renderStockAdjustmentRegister=inventory;
inventory=async function(c){await renderStockAdjustmentRegister(c);if(!currentUser||!['admin','inventory'].includes(currentUser.role))return;const rows=await api('/api/stock-adjustments');const page=c.querySelector('.page');const card=document.createElement('div');card.className='card';card.style.marginTop='16px';card.innerHTML='<h3>Recent Stock Adjustments</h3><div class="muted">Every correction is recorded with its reason.</div><table class="table"><tr><th>Date</th><th>Item</th><th>Warehouse</th><th>Direction</th><th>Qty</th><th>Reason</th><th>Recorded by</th><th>Reference</th></tr>'+rows.map(x=>'<tr><td>'+new Date(x.created_at).toLocaleString()+'</td><td>'+esc(x.product)+'</td><td>'+esc(x.warehouse)+'</td><td><span class="badge '+(x.direction==='IN'?'in':'out')+'">'+esc(x.direction)+'</span></td><td>'+esc(x.qty)+'</td><td>'+esc(x.reason)+'</td><td>'+esc(x.recorded_by)+'</td><td>'+esc(x.reference)+'</td></tr>').join('')+'</table>';page.appendChild(card)};
